// Java Backend – owner-contributed questions (CSV), part 4: microservices, Kafka, testing, security,
// design patterns, architecture, performance and observability.
import { kp, Q } from './kp.js';

const MS = 'Microservices', K = 'Kafka', T = 'Testing', SEC = 'Security', DP = 'Design Patterns', SD = 'System Design', PF = 'JVM & Performance', OB = 'Observability', TR = 'Troubleshooting', SB = 'Spring Boot';
const src = (n) => ({ source: `owner-csv-${n}` });

export const JB_ARCH = [
  Q('jb-218', MS, 'MS', 'concept', 'How do microservices communicate with each other?',
    [kp('Synchronous: REST/HTTP or gRPC', 'rest', 'http', 'grpc', 'synchronous'), kp('Asynchronous: messaging via Kafka/RabbitMQ events', 'asynchronous', 'kafka', 'rabbitmq', 'event*', 'messag*'), kp('Service discovery / gateway / load balancing', 'service discovery', 'gateway', 'load balanc*', 'kubernetes service*'), kp('Resilience: timeouts, retries, circuit breakers', 'timeout*', 'retr*', 'circuit breaker*'), kp('Contracts and versioning, propagation of auth/trace context', 'contract*', 'openapi', 'schema', 'trace context', 'token')],
    'There are two main styles. Synchronous request response uses REST over HTTP, often with OpenFeign or WebClient, or gRPC for efficient internal calls; the caller waits for the answer, which is simple but couples availability. Asynchronous messaging publishes events or commands to a broker such as Kafka or RabbitMQ, and consumers process them independently, which decouples services and absorbs spikes at the cost of eventual consistency. Services find each other through service discovery, such as Kubernetes services or Eureka, behind load balancing and often an API gateway at the edge. Every call needs timeouts, retries and circuit breakers, explicit contracts like OpenAPI or schema registry, and propagation of the auth token and trace context.',
    'How do you decide between a REST call and an event for a given interaction?', src(218)),

  Q('jb-219', MS, 'MS', 'concept', 'What is synchronous versus asynchronous communication?',
    [kp('Synchronous: caller waits for the response (REST, gRPC)', 'caller waits', 'waits', 'blocking', 'request response'), kp('Temporal coupling: callee must be available, latency adds up', 'temporal coupling', 'available', 'latency adds', 'chain'), kp('Asynchronous: send a message and continue (queue/events)', 'asynchronous', 'message', 'queue', 'fire and forget', 'event*'), kp('Decoupling, buffering, retries but eventual consistency and complexity', 'decoupl*', 'buffer*', 'eventual consistency', 'complex*'), kp('Choose: need an immediate answer vs background reaction', 'immediate answer', 'background', 'choose')],
    'In synchronous communication the caller sends a request and waits for the response, as with REST or gRPC. It is simple and gives an immediate answer, but it creates temporal coupling: the callee must be available right now, latency adds up along a chain of calls, and one slow service can block threads in all its callers. In asynchronous communication the sender publishes a message or event to a queue or topic and continues; consumers process it later. That decouples availability, buffers traffic spikes and allows retries, but it brings eventual consistency, harder debugging, ordering and duplicate handling. I choose synchronous when the user needs an immediate answer, and asynchronous for background reactions such as notifications.',
    'Is calling a REST API with WebClient non-blocking the same as asynchronous communication?', src(219)),

  Q('jb-222', MS, 'MS', 'concept', 'What is service registration?',
    [kp('Instances register their network location with a registry', 'register*', 'registry', 'network location', 'host and port'), kp('Self-registration vs third-party registration (platform)', 'self registration', 'third party', 'platform'), kp('Heartbeats/health checks and deregistration', 'heartbeat*', 'health check*', 'deregist*'), kp('Examples: Eureka, Consul, Kubernetes endpoints', 'eureka', 'consul', 'kubernetes')],
    'Service registration is how a running service instance makes its network location, host and port plus metadata, known to a service registry so others can discover it. With self registration the instance registers itself on startup, as a Spring Boot app does with the Eureka or Consul client, and sends periodic heartbeats; if heartbeats stop, the registry deregisters it, and it deregisters itself on graceful shutdown. With third party registration the platform does it: in Kubernetes, pods that pass their readiness health checks are added to the endpoints behind a Service automatically, so applications need no registry client. Discovery then uses the registry to find healthy instances.',
    'Why is a readiness probe important for service registration in Kubernetes?', src(222)),

  Q('jb-224', MS, 'MS', 'concept', 'Explain retry, timeout, fallback, and bulkhead patterns.',
    [kp('Timeout: never wait forever for a dependency', 'timeout*', 'wait forever'), kp('Retry with backoff and jitter for transient errors, only idempotent', 'retr*', 'backoff', 'jitter', 'idempotent'), kp('Fallback: degraded response when a call fails', 'fallback', 'degraded', 'default'), kp('Bulkhead: isolate resources per dependency', 'bulkhead', 'isolat*', 'separate pool*'), kp('Implemented with Resilience4j alongside circuit breaker', 'resilience4j', 'circuit breaker')],
    'These are resilience patterns for calls to other services. A timeout bounds how long you wait for a dependency, so a slow service cannot hold your threads forever; every remote call needs connect and read timeouts. A retry repeats a failed call for transient errors, with exponential backoff and jitter and a small maximum, and only for idempotent operations, otherwise you may create duplicates or amplify an outage. A fallback returns a degraded response when the call fails, such as cached data, a default value or a friendly message. A bulkhead isolates resources per dependency, for example a separate thread pool or semaphore limit, so one failing dependency cannot exhaust everything. In Spring these come from Resilience4j together with the circuit breaker.',
    'In which order should retry and circuit breaker be applied, and why?', src(224)),

  Q('jb-226', MS, 'MS', 'design', 'How would you propagate correlation IDs across multiple services?',
    [kp('Generate at the edge if missing (gateway)', 'gateway', 'edge', 'generate*', 'if missing'), kp('Pass in headers: traceparent / X-Correlation-Id', 'header*', 'traceparent', 'x-correlation-id', 'w3c'), kp('Put into MDC so every log line includes it', 'mdc', 'log line*', 'logging'), kp('Propagate through HTTP clients and Kafka message headers', 'kafka header*', 'message header*', 'webclient', 'resttemplate', 'interceptor*'), kp('Use Micrometer Tracing / OpenTelemetry instrumentation; async context', 'micrometer tracing', 'opentelemetry', 'async', 'context propagation')],
    'The id is generated at the edge, usually by the API gateway or the first service, if the incoming request does not already have one. It travels in headers on every hop; today the standard is the W3C traceparent header used by distributed tracing, and some teams also add an X-Correlation-Id header. In each service a servlet filter reads it and puts it into the logging MDC, so every log line includes it and you can search all logs for one request. Outgoing HTTP clients like RestTemplate and WebClient add it through interceptors, and Kafka producers add it to message headers so consumers continue the chain. Micrometer Tracing or OpenTelemetry instrumentation does most of this automatically, including async context propagation across thread pools.',
    'How do you keep the correlation id when work moves to another thread?', src(226)),

  Q('jb-227', MS, 'MS', 'concept', 'What is the difference between centralized and decentralized configuration?',
    [kp('Centralized: config server/store shared by services', 'centrali*', 'config server', 'spring cloud config', 'consul', 'app configuration'), kp('Decentralized: each service owns config in its repo/env', 'decentrali*', 'own repo', 'each service', 'environment variable*'), kp('Benefits: consistency, auditing, runtime refresh', 'consisten*', 'audit*', 'refresh', 'dynamic'), kp('Risks: single point of failure, coupling; decentral risk of drift', 'single point of failure', 'drift', 'coupling'), kp('Secrets kept in a vault either way', 'vault', 'secret*', 'key vault')],
    'With centralized configuration, settings for all services live in one place, such as Spring Cloud Config backed by Git, Consul, Kubernetes ConfigMaps managed centrally or Azure App Configuration, and services fetch them at startup or refresh at runtime. That gives consistency, auditing and history, one place to change shared values and dynamic refresh, but the config server becomes a critical dependency and a possible single point of failure, and teams become coupled. With decentralized configuration each service owns its config in its own repository and deployment, injected through environment variables, which keeps services autonomous but risks drift and duplicated values. Either way secrets belong in a vault, not in config files.',
    'What happens to your services if the config server is down during startup?', src(227)),

  Q('jb-228', MS, 'MS', 'concept', 'Why should microservices own their databases?',
    [kp('Database per service: loose coupling and independent deployment', 'database per service', 'loose coupling', 'independent*', 'autonomy'), kp('Shared DB couples schemas and releases', 'shared database', 'schema change*', 'coupl*'), kp('Encapsulation: access data only through the owning API', 'api', 'encapsulat*', 'owning service'), kp('Independent scaling and technology choice', 'scal*', 'technology', 'polyglot'), kp('Cost: no joins/transactions across services, need events/sagas', 'joins', 'distributed transaction*', 'saga*', 'eventual consistency', 'events')],
    'If several services share one database, they are coupled through the schema: one team cannot change a table without coordinating releases with every other team that reads it, and a heavy query from one service can slow all others. That destroys the main benefit of microservices, independent deployment. With a database per service, each service owns its data and others access it only through its API or events, so the data is encapsulated, the schema can evolve freely, the database can scale independently, and each team can pick a fitting technology such as PostgreSQL or a document store. The cost is that you lose cross service joins and ACID transactions, so you use events, sagas and eventual consistency.',
    'How would you build a report that needs data from five services?', src(228)),

  Q('jb-232', MS, 'SL', 'concept', 'What is the difference between eventual consistency and strong consistency?',
    [kp('Strong: every read sees the latest committed write', 'strong consistency', 'latest write', 'latest committed'), kp('Eventual: replicas converge over time, reads may be stale', 'eventual consistency', 'converge', 'stale'), kp('CAP / trade-off with availability and latency', 'cap', 'availability', 'latency', 'partition*'), kp('Examples: bank balance vs feed/likes/search index', 'balance', 'likes', 'search index', 'example'), kp('Handling eventual consistency in UX and code', 'idempoten*', 'read your writes', 'ui', 'compensat*')],
    'With strong consistency every read returns the latest committed write, as if there were one copy of the data; a single relational database transaction gives you this. With eventual consistency, updates propagate asynchronously to replicas or other services, so for a while reads may be stale, but if writes stop all copies converge to the same value. The CAP theorem and the PACELC refinement explain the trade off: during a network partition you choose availability or consistency, and even without one you trade latency for consistency. Money movements and inventory reservation usually need strong consistency, while a social feed, like counts or a search index can be eventually consistent. Systems then need idempotent consumers, read your writes tricks and clear UI states.',
    'How do you give a user read-your-writes behaviour in an eventually consistent system?', src(232)),

  Q('jb-234', MS, 'SL', 'scenario', 'How would you handle partial failures when one microservice becomes unavailable?',
    [kp('Timeouts and circuit breaker to fail fast', 'timeout*', 'circuit breaker', 'fail fast'), kp('Graceful degradation with fallbacks/cached data', 'graceful degradation', 'fallback*', 'cached', 'degrad*'), kp('Asynchronous queue to retry later', 'queue', 'retry later', 'asynchronous', 'outbox'), kp('Idempotency and compensation for half-done work', 'idempoten*', 'compensat*', 'saga'), kp('Monitoring, alerts and clear errors to clients', 'alert*', 'monitor*', '503', 'error message')],
    'First I stop the failure from spreading: every call to that service has a timeout and goes through a circuit breaker, so once it is clearly down we fail fast instead of piling up threads. Then I decide per feature how to degrade gracefully. Non critical data can use a fallback, such as cached recommendations or hiding a widget, while the rest of the page works. For writes that can wait, I put the request on a queue or use the outbox pattern so it is retried later when the service recovers. If a multi step operation was half done, idempotent retries and saga compensation bring it back to a consistent state. Clients get a clear 503 or a pending status, and monitoring alerts the owning team.',
    'Which features of an e-commerce checkout can degrade, and which must fail?', src(234)),

  Q('jb-235', MS, 'SL', 'design', 'How do you prevent cascading failures across microservices?',
    [kp('Timeouts shorter than the caller budget', 'timeout*', 'deadline*', 'budget'), kp('Circuit breakers', 'circuit breaker*'), kp('Bulkheads and limited concurrency', 'bulkhead*', 'concurrency limit*', 'isolat*'), kp('Controlled retries: backoff, jitter, retry budgets', 'backoff', 'jitter', 'retry budget*', 'retry storm*'), kp('Load shedding, rate limiting, autoscaling, async decoupling', 'load shedding', 'rate limit*', 'autoscal*', 'queue*')],
    'A cascading failure happens when one slow service makes its callers wait, they run out of threads, and their own callers fail in turn. I prevent it at every hop. Each call has a timeout shorter than the caller time budget, ideally with deadline propagation. Circuit breakers stop calling a failing dependency and let it recover. Bulkheads give each dependency its own limited thread pool or semaphore, so one bad dependency cannot exhaust all resources. Retries are controlled with exponential backoff, jitter and retry budgets to avoid retry storms. Services protect themselves with rate limiting and load shedding, returning 503 early when overloaded, autoscaling adds capacity, and queues decouple non urgent work.',
    'What is a retry storm and how do retry budgets prevent it?', src(235)),

  Q('jb-243', K, 'MS', 'concept', 'What is an offset in Kafka?',
    [kp('Sequential position of a record within a partition', 'position', 'partition', 'sequential'), kp('Consumer group commits offsets to __consumer_offsets', 'commit*', 'consumer_offsets', 'consumer group'), kp('Resume from committed offset after restart/rebalance', 'resume', 'restart', 'rebalance'), kp('Reset/replay with auto.offset.reset or seek', 'auto.offset.reset', 'earliest', 'latest', 'replay', 'seek')],
    'An offset is the sequential position of a record within one partition: the first record is 0, the next 1, and so on. It is unique only per partition, not per topic. Consumers track how far they have read by committing offsets per partition for their consumer group; Kafka stores them in the internal __consumer_offsets topic. After a restart or a rebalance, a consumer resumes from the last committed offset, which is why committing before or after processing decides at most once or at least once behaviour. If no committed offset exists, auto.offset.reset decides whether to start from earliest or latest, and you can replay data by resetting offsets with kafka-consumer-groups or calling seek.',
    'What happens to committed offsets when the retention period deletes old records?', src(243)),

  Q('jb-249', K, 'MS', 'concept', 'What is a Kafka rebalance, and when does it happen?',
    [kp('Reassigning partitions among consumers in a group', 'reassign*', 'partitions', 'consumer group'), kp('Triggers: consumer joins/leaves/crashes, max.poll.interval exceeded, partitions added', 'joins', 'leaves', 'crash*', 'max.poll.interval', 'new partition*'), kp('Pauses consumption; eager stop-the-world', 'pause*', 'stop the world', 'eager'), kp('Cooperative/incremental rebalancing, static membership', 'cooperative', 'incremental', 'static membership', 'group.instance.id'), kp('Commit offsets in rebalance listener', 'rebalancelistener', 'onpartitionsrevoked', 'commit')],
    'A rebalance is the process where the group coordinator reassigns topic partitions among the consumers of a consumer group. It happens when a consumer joins, for example during scaling or a rolling deploy, when one leaves or crashes and misses heartbeats, when a consumer exceeds max.poll.interval.ms because processing took too long, or when partitions are added to a subscribed topic. With the classic eager protocol all consumers stop and give up their partitions, a stop the world pause in consumption. Cooperative incremental rebalancing moves only the affected partitions, and static membership with group.instance.id avoids rebalances on quick restarts. Commit offsets in onPartitionsRevoked of a ConsumerRebalanceListener to avoid reprocessing.',
    'Why do frequent rebalances during deployments hurt, and how do you reduce them?', src(249)),

  Q('jb-250', K, 'MS', 'design', 'How do you handle duplicate messages in Kafka consumers?',
    [kp('At-least-once delivery means duplicates happen', 'at least once', 'duplicates', 'redeliver*'), kp('Idempotent consumer: store processed message ids', 'idempotent consumer', 'processed', 'message id', 'event id'), kp('Unique constraint / upsert in the same transaction', 'unique constraint', 'upsert', 'same transaction'), kp('Natural idempotency: set state not increment, version checks', 'version*', 'set the state', 'natural*'), kp('Exactly-once only within Kafka (transactions)', 'exactly once', 'kafka transaction*', 'read process write')],
    'With at least once delivery duplicates are normal: a consumer can process a record and crash before committing the offset, or a producer retry can write twice, so the record is redelivered. The robust answer is an idempotent consumer. Each event carries a unique event id, and the consumer records processed ids in a table with a unique constraint, inserted in the same database transaction as the business change, so a duplicate fails the insert and is skipped. Where possible I make operations naturally idempotent: set a status instead of incrementing, use upserts, or check an entity version. Kafka exactly once semantics with transactions only cover read process write flows within Kafka, not external side effects such as database writes.',
    'How long should you keep processed message ids?', src(250)),

  Q('jb-251', K, 'SL', 'design', 'How would you implement retry mechanisms and dead-letter topics?',
    [kp('Classify transient vs permanent errors', 'transient', 'permanent', 'poison', 'classif*'), kp('In-place retries with backoff (DefaultErrorHandler)', 'defaulterrorhandler', 'backoff', 'blocking retr*'), kp('Non-blocking retry topics with delays', 'retry topic*', 'non blocking', 'retryabletopic', 'delay'), kp('Dead-letter topic after max attempts with error headers', 'dead letter', 'dlt', 'max attempts', 'headers'), kp('Monitor and reprocess DLT; keep idempotency/ordering in mind', 'reprocess', 'replay', 'alert*', 'ordering', 'idempoten*')],
    'First I classify errors: transient ones, such as a downstream timeout, are worth retrying, while permanent ones, such as a deserialization failure or validation error, a poison message, are not. In Spring Kafka the DefaultErrorHandler does a few blocking retries in place with exponential backoff, which keeps ordering but stalls the partition. For longer delays I use non blocking retry topics with RetryableTopic, for example retry-1m and retry-10m topics, so the main partition keeps flowing at the cost of ordering. After max attempts the record goes to a dead letter topic, a DLT, with headers carrying the exception, stack trace and original topic, partition and offset. I alert on DLT traffic and have a tool to inspect, fix and replay records, with idempotent consumers.',
    'When would non-blocking retry topics break your business ordering requirements?', src(251)),

  Q('jb-252', K, 'SL', 'scenario', 'What happens when a consumer takes longer to process a message than the configured poll interval?',
    [kp('max.poll.interval.ms exceeded, consumer considered failed', 'max.poll.interval', 'considered dead', 'considered failed', 'leaves the group'), kp('Rebalance assigns partitions to others', 'rebalance', 'reassign*'), kp('Offset commit fails, messages reprocessed / duplicates', 'commitfailedexception', 'reprocess*', 'duplicate*'), kp('Can loop forever: rebalance storm', 'loop', 'storm', 'again and again'), kp('Fixes: smaller max.poll.records, larger interval, async processing with pause', 'max.poll.records', 'pause', 'resume', 'increase')],
    'Kafka expects the consumer to call poll again within max.poll.interval.ms, five minutes by default. If processing the batch takes longer, the consumer is considered failed and leaves the group, which triggers a rebalance that gives its partitions to other consumers. When the slow consumer finally finishes and tries to commit, the commit fails with CommitFailedException, so those records are processed again by another consumer, causing duplicates. If every batch is slow, this can loop forever as a rebalance storm with no progress. Fixes are to lower max.poll.records so each poll returns less work, increase max.poll.interval.ms carefully, speed up processing, or hand work to a separate thread pool while pausing the partitions.',
    'How is max.poll.interval.ms different from session.timeout.ms?', src(252)),

  Q('jb-255', K, 'SL', 'concept', 'How does Kafka achieve high throughput and fault tolerance?',
    [kp('Sequential append-only log on disk, page cache', 'append only', 'sequential', 'page cache'), kp('Zero-copy transfer, batching and compression', 'zero copy', 'sendfile', 'batch*', 'compression'), kp('Partitioning spreads load across brokers and consumers', 'partition*', 'parallel*', 'brokers'), kp('Replication with leader/followers and ISR', 'replication', 'leader', 'follower*', 'isr', 'in sync replicas'), kp('acks=all, min.insync.replicas, controller failover', 'acks', 'min.insync.replicas', 'failover', 'controller', 'kraft')],
    'For throughput, each partition is an append only log written sequentially to disk, which is very fast, and reads are served largely from the operating system page cache. Brokers use zero copy, the sendfile system call, to move data from disk to the network without copying it through the JVM. Producers batch records and compress them, so network and disk handle large chunks. Topics are split into partitions spread across brokers, so load and consumers scale in parallel. For fault tolerance, every partition is replicated: one leader handles writes and followers copy it, forming the in sync replicas, the ISR. With acks=all and min.insync.replicas of 2, an acknowledged write survives a broker failure, and the controller, now KRaft, elects a new leader on failover.',
    'What trade-off do you make by setting acks=1 instead of acks=all?', src(255)),

  Q('jb-256', K, 'SL', 'design', 'How would you design an event-driven architecture using Kafka and Spring Boot?',
    [kp('Identify domain events and topics, key by aggregate id', 'domain event*', 'topic*', 'key*', 'aggregate id'), kp('Producers: KafkaTemplate with outbox for reliability', 'kafkatemplate', 'outbox', 'producer*'), kp('Consumers: @KafkaListener, consumer groups, idempotency', 'kafkalistener', 'consumer group*', 'idempoten*'), kp('Schemas: Avro/JSON schema registry, versioning', 'schema registry', 'avro', 'schema*', 'versioning'), kp('Error handling, DLT, observability and ordering', 'dead letter', 'dlt', 'tracing', 'ordering', 'monitor*')],
    'I start from the domain: identify domain events such as OrderPlaced and PaymentCompleted, give each a topic or a topic per aggregate, and use the aggregate id as the message key so events of one order stay ordered in one partition. Producing services write the business change and an outbox row in one transaction, and a relay or Debezium publishes to Kafka, so no event is lost; simpler cases use KafkaTemplate with idempotent producers. Consumers are Spring Boot services with KafkaListener in their own consumer groups, scaled up to the partition count, and they are idempotent. Events have schemas in Avro or JSON Schema with a schema registry and backward compatible versioning. I add retries, a DLT, tracing headers and lag monitoring.',
    'How would you rebuild a new service read model from existing events?', src(256)),

  Q('jb-258', T, 'EM', 'concept', 'What is unit testing, and why is it important?',
    [kp('Tests one unit (class/method) in isolation', 'unit', 'in isolation', 'single class'), kp('Dependencies replaced with mocks/fakes', 'mock*', 'fake*', 'stub*'), kp('Fast, automated feedback in CI', 'fast', 'automated', 'ci', 'feedback'), kp('Catches regressions, enables refactoring, documents behaviour', 'regression*', 'refactor*', 'document*'), kp('Arrange-act-assert, JUnit 5', 'arrange', 'given when then', 'junit')],
    'A unit test checks one small unit of code, typically a class or method, in isolation from databases, networks and other services, whose dependencies are replaced with mocks or simple fakes. Unit tests are fast, so thousands can run on every build in CI and give developers feedback within seconds. They catch regressions when code changes, give the confidence needed to refactor safely, and document the expected behaviour, including edge cases and error paths. A good unit test follows arrange act assert, or given when then, tests behaviour rather than implementation details and has one clear reason to fail. In Java they are usually written with JUnit 5, Mockito and AssertJ.',
    'What makes a unit test brittle?', src(258)),

  Q('jb-259', T, 'EM', 'concept', 'What is the difference between JUnit 4 and JUnit 5?',
    [kp('JUnit 5 = Platform + Jupiter + Vintage modules', 'jupiter', 'platform', 'vintage', 'modular'), kp('Annotation changes: @BeforeEach/@AfterEach, @Disabled', 'beforeeach', 'aftereach', 'disabled', 'before'), kp('Extensions model replaces runners and rules', 'extension*', 'extendwith', 'runwith', 'rules'), kp('New features: @ParameterizedTest, @Nested, @DisplayName, assertThrows', 'parameterizedtest', 'nested', 'displayname', 'assertthrows'), kp('Java 8+ lambdas; public not required', 'lambda*', 'java 8', 'public')],
    'JUnit 5 is a rewrite and is modular: the JUnit Platform launches tests, Jupiter is the new programming model and Vintage runs old JUnit 4 tests. Annotations changed: Before and After became BeforeEach and AfterEach, BeforeClass became BeforeAll, Ignore became Disabled. The single runner and rules mechanism of JUnit 4, RunWith and Rule, was replaced by a composable extension model with ExtendWith, so Spring and Mockito extensions can be combined. JUnit 5 adds ParameterizedTest with various sources, Nested test classes, DisplayName, tags, dynamic tests and assertThrows instead of expected exceptions or rules. It requires Java 8, uses lambdas in assertions, and test classes and methods no longer need to be public.',
    'How would you migrate a large JUnit 4 test suite gradually?', src(259)),

  Q('jb-260', T, 'MS', 'concept', 'What is Mockito, and how do you mock dependencies?',
    [kp('Mocking framework for Java unit tests', 'mocking framework', 'mockito', 'test double*'), kp('Create mocks with mock() or @Mock', 'mock(', '@mock', 'mock'), kp('Stub with when().thenReturn()/thenThrow()', 'when', 'thenreturn', 'thenthrow', 'stub*'), kp('Verify interactions with verify()', 'verify', 'interaction*', 'times'), kp('ArgumentCaptor, spies, MockitoExtension', 'argumentcaptor', 'spy', 'mockitoextension')],
    'Mockito is the most widely used mocking framework for Java unit tests. It creates test doubles that stand in for real dependencies, so a service can be tested without a database or HTTP client. You create mocks with Mockito.mock or the Mock annotation together with MockitoExtension in JUnit 5. You stub behaviour with when(repository.findById(1L)).thenReturn(Optional.of(order)) or thenThrow to simulate failures. After calling the code under test you verify interactions, for example verify(emailService, times(1)).send(any()), and use an ArgumentCaptor to inspect the argument passed. Spies wrap a real object and stub only some methods. Do not mock types you do not own or value objects.',
    'Why is over-mocking considered a test smell?', src(260)),

  Q('jb-261', T, 'MS', 'concept', 'What is the difference between unit, integration, and end-to-end testing?',
    [kp('Unit: one class in isolation, fast, many', 'unit test*', 'isolation', 'fast'), kp('Integration: several components with real infrastructure (DB, Kafka)', 'integration test*', 'real database', 'testcontainers', 'infrastructure'), kp('End-to-end: whole system through UI/API like a user', 'end to end', 'whole system', 'user journey*', 'deployed'), kp('Test pyramid: many unit, fewer integration, few E2E', 'test pyramid', 'pyramid', 'fewer'), kp('Trade-offs: speed, confidence, flakiness', 'slow', 'flak*', 'confidence', 'cost')],
    'A unit test checks one class or function in isolation with dependencies mocked; it is fast, cheap and precise, so you have many. An integration test checks several components working together with real infrastructure, for example a repository against a real PostgreSQL in Testcontainers, a REST controller with the full Spring context, or a Kafka listener with a real broker; it catches wiring, mapping and SQL problems that mocks hide but is slower. An end to end test exercises the whole deployed system through its UI or public API like a real user journey, such as placing an order; it gives the most confidence but is slow, expensive and often flaky. The test pyramid suggests many unit tests, fewer integration tests and a few critical end to end tests.',
    'Where do contract tests fit in the test pyramid?', src(261)),

  Q('jb-262', T, 'MS', 'concept', 'What is the difference between @Mock and @InjectMocks?',
    [kp('@Mock creates a mock instance of a dependency', '@mock', 'mock instance', 'creates a mock'), kp('@InjectMocks creates the real class under test', 'injectmocks', 'class under test', 'real instance'), kp('Injects the mocks via constructor, setter or field', 'constructor', 'setter', 'field injection', 'injects'), kp('Requires MockitoExtension / openMocks', 'mockitoextension', 'openmocks', 'extendwith'), kp('Silent failure if injection is not possible; prefer constructor', 'silent*', 'null', 'prefer constructor')],
    'Mock creates a mock instance of a dependency, such as an OrderRepository, whose methods do nothing and return defaults until you stub them. InjectMocks creates a real instance of the class under test, such as OrderService, and injects the mocks declared in the test into it, trying constructor injection first, then setter injection, then field injection. Both need MockitoExtension in JUnit 5, or MockitoAnnotations.openMocks. A pitfall is that if Mockito cannot inject, it fails silently and you get a NullPointerException later, so I prefer constructor injection in production code, and some teams simply construct the service themselves with new and pass the mocks explicitly, which is clearer.',
    'What is the difference between @Mock and @MockBean or @MockitoBean in Spring tests?', src(262)),

  Q('jb-263', T, 'MS', 'concept', 'What is Testcontainers, and why is it useful?',
    [kp('Library that starts real dependencies in Docker containers for tests', 'docker', 'container*', 'testcontainers'), kp('Real PostgreSQL, Kafka, Redis instead of H2/mocks', 'postgresql', 'kafka', 'redis', 'h2'), kp('Production-like behaviour, catches SQL/dialect issues', 'production like', 'dialect', 'realistic', 'same version'), kp('Throwaway, isolated, managed lifecycle in JUnit', 'throwaway', 'isolated', 'lifecycle', 'junit'), kp('Spring Boot @ServiceConnection integration; reuse for speed', 'serviceconnection', 'dynamicpropertysource', 'reuse', 'singleton container*')],
    'Testcontainers is a Java library that starts real dependencies in throwaway Docker containers from your tests, such as PostgreSQL, Kafka, Redis, Elasticsearch or LocalStack, and removes them afterwards. Instead of testing against an in memory H2 database or mocks, you run integration tests against the same database engine and version as production, so you catch SQL dialect differences, migration problems, constraints, serialization and broker configuration issues early. Containers are isolated per test run, so tests are repeatable on any machine and in CI that has Docker. The JUnit 5 extension manages their lifecycle, and Spring Boot integrates with ServiceConnection or DynamicPropertySource; singleton or reused containers keep the suite fast.',
    'How would you keep a Testcontainers test suite fast in CI?', src(263)),

  Q('jb-265', T, 'MS', 'scenario', 'How do you test asynchronous Kafka consumers?',
    [kp('Unit test the handler logic directly without Kafka', 'unit test', 'handler', 'directly', 'listener method'), kp('Integration test with embedded Kafka or Testcontainers Kafka', 'embeddedkafka', 'embedded kafka', 'testcontainers'), kp('Produce a message, then wait with Awaitility (no sleeps)', 'awaitility', 'await', 'no sleep*', 'thread.sleep'), kp('Assert side effects: DB state, outbound messages, DLT', 'side effect*', 'database', 'dead letter', 'outbound'), kp('Test failure paths: retries, poison messages, duplicates', 'retr*', 'poison', 'duplicate*', 'error handling')],
    'I split it into two levels. The business logic inside the listener is a plain method, so I unit test it directly with a message object, no Kafka involved. For integration tests I start a real broker with Testcontainers Kafka, or Spring EmbeddedKafka, run the Spring Boot context, publish a message with KafkaTemplate, and then wait for the asynchronous effect using Awaitility, such as await().atMost(10, SECONDS).untilAsserted, instead of Thread.sleep, which is slow and flaky. I assert side effects such as rows saved in the database, outbound events on another topic or a record on the dead letter topic. I also test failure paths: retries, poison messages going to the DLT and duplicate delivery being ignored.',
    'Why is Thread.sleep a bad way to wait in asynchronous tests?', src(265)),

  Q('jb-269', SEC, 'SL', 'concept', 'How would you prevent SQL injection in a Java application?',
    [kp('Parameterized queries / PreparedStatement bind variables', 'preparedstatement', 'parameteri*', 'bind variable*', 'bind parameter*'), kp('JPA named parameters, never concatenate', 'named parameter*', 'concatenat*', 'jpql'), kp('Whitelist dynamic identifiers like sort columns', 'whitelist', 'allow list', 'sort column*', 'identifier*'), kp('Input validation and least-privilege DB user', 'input validation', 'least privilege', 'database user'), kp('Static analysis, testing, WAF as defence in depth', 'static analysis', 'sast', 'waf', 'defence in depth', 'defense in depth')],
    'SQL injection happens when user input is concatenated into a SQL string and changes the query structure. The main defence is parameterized queries: use PreparedStatement with bind variables in JDBC, named parameters in JPQL and Spring Data Query methods, and never build queries by string concatenation, including inside native queries. Values like table or column names cannot be bind parameters, so dynamic identifiers such as a sort column must be checked against a whitelist of allowed values. I also validate input types and lengths, connect with a least privilege database user that cannot drop tables, and use static analysis tools in CI, code review and a WAF as defence in depth.',
    'Is a Spring Data derived query method like findByEmail safe from SQL injection?', src(269)),

  Q('jb-270', SEC, 'SL', 'design', 'How would you securely manage passwords, API keys, and database credentials?',
    [kp('Never in source code or Git; scan for leaks', 'source code', 'git', 'secret scanning', 'gitleaks', 'never commit'), kp('Secret manager: Vault, AWS Secrets Manager, Azure Key Vault', 'vault', 'secrets manager', 'key vault', 'secret manager'), kp('Inject at runtime, managed identity / workload identity', 'runtime', 'managed identit*', 'workload identity', 'inject*'), kp('Rotation, short-lived/dynamic credentials, least privilege', 'rotat*', 'short lived', 'dynamic', 'least privilege'), kp('User passwords hashed with bcrypt/argon2, not encrypted; do not log secrets', 'bcrypt', 'argon2', 'hash*', 'log*')],
    'Secrets never go into source code, application.yml in Git or Docker images, and I run secret scanning such as gitleaks in CI to catch leaks. They live in a secret manager, HashiCorp Vault, AWS Secrets Manager or Azure Key Vault, and are injected at runtime through environment variables, mounted files or Spring Cloud Vault. Where possible the application authenticates to the cloud with a managed identity or workload identity so no static credential exists at all. Credentials are rotated regularly, ideally short lived dynamic database credentials from Vault, with least privilege per service. User passwords are a different case: they are never stored or encrypted but hashed with bcrypt or Argon2 with a salt, and secrets are never written to logs.',
    'How would you rotate a database password without downtime?', src(270)),

  Q('jb-272', SEC, 'SL', 'design', 'How would you implement role-based access control in Spring Security?',
    [kp('Roles/authorities from users or JWT claims', 'role*', 'authorit*', 'claims', 'jwt'), kp('URL rules in SecurityFilterChain with hasRole/hasAuthority', 'securityfilterchain', 'hasrole', 'hasauthority', 'requestmatchers'), kp('Method security with @PreAuthorize', 'preauthorize', 'enablemethodsecurity', 'method security'), kp('Object-level checks for ownership', 'ownership', 'object level', 'own resources', 'permissionevaluator'), kp('Deny by default and test authorization rules', 'deny by default', 'denyall', 'test*')],
    'First roles or authorities must reach Spring Security: from a user database through a UserDetailsService, or, in a resource server, from JWT claims such as roles or scopes mapped by a JwtAuthenticationConverter into GrantedAuthority objects. Then I enforce them in two places. URL rules in the SecurityFilterChain, for example requestMatchers("/admin/**").hasRole("ADMIN") and authenticated for everything else, with deny by default. Method security with EnableMethodSecurity and PreAuthorize("hasAuthority(orders:write)") protects service methods. Roles alone are not enough for data, so I add object level ownership checks, such as PreAuthorize with a bean method or a PermissionEvaluator, so users only access their own resources. I write tests with WithMockUser for each role.',
    'What is the difference between hasRole and hasAuthority?', src(272)),

  Q('jb-273', DP, 'EM', 'concept', 'What are design patterns, and why are they useful?',
    [kp('Reusable, proven solutions to common design problems', 'reusable', 'proven', 'common problem*', 'solution*'), kp('Categories: creational, structural, behavioral (GoF)', 'creational', 'structural', 'behavioral', 'behavioural', 'gang of four'), kp('Shared vocabulary for communication', 'vocabulary', 'communicat*', 'common language'), kp('Improve maintainability and flexibility; do not overuse', 'maintainab*', 'flexib*', 'overuse', 'over engineer*'), kp('Examples in Java/Spring', 'singleton', 'factory', 'strategy', 'proxy', 'spring')],
    'Design patterns are reusable, proven solutions to common problems in software design, described as templates rather than finished code. The classic Gang of Four book groups them into creational patterns about object creation, such as Singleton, Factory and Builder; structural patterns about composing classes, such as Adapter, Decorator and Proxy; and behavioural patterns about interaction, such as Strategy, Observer and Template Method. They are useful because they capture experience, make code more flexible and maintainable, and give the team a shared vocabulary: saying use a strategy here communicates a whole design. Spring itself uses many, such as Proxy for transactions and Template Method in JdbcTemplate. They should not be overused, which leads to over engineering.',
    'Can you give an example where applying a design pattern made code worse?', src(273)),

  Q('jb-274', DP, 'MS', 'concept', 'Explain Singleton, Factory, and Abstract Factory patterns.',
    [kp('Singleton: one instance with global access, thread-safe (enum/holder)', 'singleton', 'one instance', 'enum', 'holder'), kp('Factory Method: subclasses/method decide which class to create', 'factory method', 'decides which', 'creation'), kp('Abstract Factory: families of related objects', 'abstract factory', 'families', 'related objects'), kp('Decouple clients from concrete classes', 'decoupl*', 'concrete class*', 'interface'), kp('Spring examples: singleton beans, FactoryBean', 'spring', 'factorybean', 'singleton scope')],
    'Singleton ensures a class has only one instance with a global access point. In plain Java the safest implementations are an enum or the initialization on demand holder idiom, which are thread safe without locking; in Spring you rarely write one because beans are singleton scope by default, and singletons can hurt testability. Factory Method defines a method that creates objects, letting a subclass or a parameter decide which concrete class to create, such as a NotificationFactory returning an EmailSender or SmsSender. Abstract Factory goes further: it creates families of related objects that must be used together, such as UI components for a theme or clients for a cloud provider. Both decouple clients from concrete classes; Spring FactoryBean is an example.',
    'How can reflection or serialization break a Singleton, and how does an enum prevent it?', src(274)),

  Q('jb-275', DP, 'MS', 'concept', 'What is the Builder pattern?',
    [kp('Creational pattern for building complex objects step by step', 'step by step', 'complex object*', 'creational'), kp('Avoids telescoping constructors with many parameters', 'telescoping', 'many parameters', 'constructor*'), kp('Readable fluent API with named setters and build()', 'fluent', 'readable', 'build'), kp('Supports immutability and validation in build', 'immutab*', 'validat*'), kp('Examples: StringBuilder, HttpRequest.newBuilder, Lombok @Builder', 'lombok', 'httprequest', 'newbuilder', 'stringbuilder')],
    'Builder is a creational pattern for constructing complex objects step by step. It solves the telescoping constructor problem, where a class with many optional parameters ends up with many constructors or one constructor with ten arguments that are easy to mix up. A builder offers a readable fluent API with named methods, such as Order.builder().customerId(42).currency("INR").express(true).build(), and the build method can validate the combination of fields before creating the object. Because the object is created in one step, it can be immutable with final fields. Java examples include HttpRequest.newBuilder, StringBuilder and Lombok Builder, and records can be combined with builders for many fields.',
    'What are the downsides of using Lombok @Builder on JPA entities?', src(275)),

  Q('jb-286', SD, 'SL', 'design', 'How would you design an inventory management system with concurrent updates?',
    [kp('Prevent overselling: atomic conditional update', 'oversell*', 'atomic', 'conditional update', 'where quantity'), kp('Optimistic locking with version and retry, or pessimistic locks', 'optimistic lock*', 'version', 'pessimistic', 'select for update'), kp('Reservations with expiry before payment', 'reservation*', 'reserve', 'expir*', 'ttl'), kp('Event-driven updates, idempotency, outbox', 'event*', 'idempoten*', 'outbox', 'kafka'), kp('Hot items: Redis counters, sharding by SKU, queues', 'redis', 'hot item*', 'sku', 'shard*', 'queue')],
    'The key requirement is never overselling while many orders update the same stock. The simplest robust approach is an atomic conditional update in the database: UPDATE stock SET quantity = quantity - :n WHERE sku = :sku AND quantity >= :n, and treating zero updated rows as out of stock. Alternatively, optimistic locking with a version column and a retry, or pessimistic SELECT FOR UPDATE for short, highly contended transactions. Checkout creates a reservation with an expiry, so stock is held until payment completes and released by a job if not. Changes are published as events through an outbox, consumers are idempotent. For flash sale hot items I use Redis atomic counters or a queue per SKU, and shard data by SKU and warehouse.',
    'How would you reconcile Redis counters with the database of record?', src(286)),

  Q('jb-288', PF, 'MS', 'concept', 'What are the common causes of slow Java applications?',
    [kp('Slow or too many database queries, missing indexes, N+1', 'database', 'n+1', 'index*', 'slow quer*'), kp('Blocking remote calls without timeouts, sequential calls', 'remote call*', 'timeout*', 'sequential', 'downstream'), kp('GC pressure / memory leaks', 'gc', 'garbage collect*', 'memory leak*', 'allocation*'), kp('Lock contention, small or exhausted pools', 'contention', 'lock*', 'connection pool', 'thread pool'), kp('Inefficient code: algorithms, serialization, logging; cold JIT', 'algorithm*', 'serializ*', 'logging', 'warm up', 'jit')],
    'In my experience most slowness comes from I/O rather than Java itself. The most common cause is the database: slow queries, missing indexes, N+1 selects and fetching too much data. Next are remote calls to other services made sequentially or without timeouts, so one slow dependency slows everything. Then memory problems: high allocation rates cause GC pressure and long pauses, and memory leaks lead to frequent full GCs. Concurrency problems follow: lock contention, synchronized hot paths, and thread or connection pools that are too small and exhausted. Finally inefficient code: wrong algorithms or data structures, heavy JSON serialization, excessive logging, regex compiled in loops, and cold JIT right after startup.',
    'How would you tell whether a slowdown is caused by GC or by the database?', src(288)),

  Q('jb-289', PF, 'MS', 'scenario', 'How would you identify CPU-intensive operations in a Java application?',
    [kp('Confirm with CPU metrics per process/thread (top -H)', 'top', 'thread*', 'cpu metric*', 'per thread'), kp('Map hot thread ids to thread dump (nid hex)', 'thread dump', 'nid', 'hex', 'jstack'), kp('Sampling profiler flame graphs: async-profiler, JFR', 'async profiler', 'flame graph*', 'jfr', 'flight recorder'), kp('Check GC/JIT threads too', 'gc thread*', 'jit', 'compiler thread*'), kp('Typical culprits and verify fix with benchmarks', 'regex', 'serializ*', 'loop*', 'jmh')],
    'First I confirm the process is CPU bound with metrics and top. To find which threads burn CPU I use top -H -p on the JVM process, convert the hot thread ids to hexadecimal and match them to the nid fields in a thread dump from jstack or jcmd, which shows the stack being executed. A few dumps in a row tell whether it is a tight loop. The better tool is a sampling profiler: async-profiler or Java Flight Recorder produce flame graphs showing exactly which methods consume CPU, with low overhead, safe even in production. I also check whether the CPU is in GC or JIT compiler threads rather than application code. Typical culprits are regex, serialization, inefficient loops and logging, and I verify fixes with JMH.',
    'Why can a sampling profiler be misleading because of safepoint bias?', src(289)),

  Q('jb-290', PF, 'MS', 'concept', 'What is profiling, and which Java profiling tools have you used?',
    [kp('Measuring where an application spends CPU, memory, time', 'profil*', 'cpu', 'memory', 'where time'), kp('Sampling vs instrumentation profilers, overhead', 'sampling', 'instrumentation', 'overhead'), kp('JFR + JDK Mission Control', 'jfr', 'flight recorder', 'mission control', 'jmc'), kp('async-profiler, VisualVM, YourKit/JProfiler', 'async profiler', 'visualvm', 'yourkit', 'jprofiler'), kp('Heap analysis with Eclipse MAT; continuous profiling', 'mat', 'heap', 'continuous profiling', 'pyroscope')],
    'Profiling is measuring where an application actually spends its resources, CPU time, memory allocations, locks and I/O waits, instead of guessing. Sampling profilers take stack snapshots periodically and have low overhead, so they are usable in production; instrumentation profilers record every call precisely but slow the application down. I have used Java Flight Recorder, built into the JDK, with JDK Mission Control to analyse CPU, allocations, GC and lock contention; async-profiler for flame graphs of CPU, allocation and wall clock time; VisualVM for quick local checks; and commercial tools such as YourKit and JProfiler. For memory I analyse heap dumps with Eclipse MAT, and continuous profiling with Pyroscope or a vendor APM helps catch regressions.',
    'How would you profile an application running inside a Kubernetes pod?', src(290)),

  Q('jb-292', OB, 'MS', 'concept', 'What metrics would you monitor for a production Java application?',
    [kp('RED: request rate, errors, duration (p95/p99)', 'request rate', 'error rate', 'latency', 'p99', 'red'), kp('JVM: heap, GC pauses, threads, CPU', 'heap', 'gc pause*', 'threads', 'cpu'), kp('Pools: DB connections, thread pools, queue sizes', 'connection pool', 'hikari', 'thread pool', 'queue'), kp('Dependencies and Kafka consumer lag', 'downstream', 'consumer lag', 'dependenc*'), kp('Business metrics and SLO-based alerting', 'business metric*', 'slo', 'alert*'), kp('Micrometer + Prometheus/Grafana', 'micrometer', 'prometheus', 'grafana')],
    'I start with the RED metrics for every endpoint: request rate, error rate and duration as percentiles such as p95 and p99, not averages. Then JVM health: heap usage after GC, GC pause time and frequency, live thread count, CPU and, in containers, memory against the limit. Then resource pools: Hikari active and pending connections, thread pool active and queue sizes, cache hit ratios. Then dependencies: latency and errors of downstream calls, circuit breaker state and Kafka consumer lag. I also track business metrics such as orders placed or payments failed, which often reveal problems first. Spring Boot exposes them through Micrometer to Prometheus and Grafana, and alerts are based on SLOs rather than every spike.',
    'Why are average response times misleading?', src(292)),

  Q('jb-293', OB, 'MS', 'concept', 'What is structured logging, and why is it useful?',
    [kp('Logs as structured key-value/JSON instead of free text', 'json', 'key value', 'structured', 'fields'), kp('Easy to search, filter and aggregate in ELK/Loki', 'search', 'filter', 'aggregat*', 'elk', 'loki', 'kibana'), kp('Consistent fields: timestamp, level, service, trace id', 'trace id', 'correlation id', 'service name', 'timestamp'), kp('MDC for contextual fields', 'mdc', 'context'), kp('Logback encoder / Spring Boot structured logging; avoid sensitive data', 'logstash encoder', 'logback', 'structured logging', 'sensitive')],
    'Structured logging means writing each log entry as structured data, usually one JSON object per line with named fields, instead of a free text sentence. A log line then has consistent fields such as timestamp, level, service name, logger, message, trace id and business keys like orderId. That makes logs easy to search, filter and aggregate in tools like ELK, Kibana or Grafana Loki: you can query all errors for one customer or count failures per endpoint without fragile regex parsing. In Java I add contextual fields through the MDC in a filter, and output JSON with the Logstash Logback encoder or the built in structured logging of Spring Boot 3.4. Sensitive data such as passwords and tokens must never be logged.',
    'How do you control log volume and cost in production?', src(293)),

  Q('jb-296', TR, 'SL', 'scenario', 'How would you investigate an API that works correctly in development but is slow in production?',
    [kp('Compare environments: data volume, configuration, resources', 'data volume', 'configuration', 'resources', 'differ*'), kp('Tracing/APM to find the slow span', 'trac*', 'apm', 'span*'), kp('Database: execution plan on production-size data, missing indexes, stats', 'execution plan', 'index*', 'production data', 'statistics'), kp('Network latency, downstream services, TLS, DNS', 'network', 'latency', 'downstream', 'dns'), kp('Concurrency: pools, GC, CPU limits/throttling under real load', 'pool*', 'gc', 'throttl*', 'load', 'cpu limit*')],
    'The code is the same, so I look for what differs between environments. Production usually has far larger data volumes, so a query that is fast on a thousand rows does a full scan on fifty million; I compare the execution plan on production size data, check missing indexes and stale statistics. I use distributed tracing or an APM to find which span is slow: database, a downstream service, or the application itself. I check network latency between zones, DNS and TLS handshakes, and production only components such as a WAF or proxy. Then concurrency: under real load, connection or thread pools may be exhausted, GC may be busy, and in Kubernetes the CPU limits may cause throttling. Configuration differences like logging level or pool sizes also matter.',
    'How would you safely reproduce production-like data volumes in a test environment?', src(296)),

  Q('jb-297', OB, 'SL', 'design', 'How would you implement distributed tracing using OpenTelemetry?',
    [kp('Traces made of spans with context propagated via W3C traceparent', 'span*', 'trace*', 'traceparent', 'context propagation'), kp('Instrumentation: Java agent auto-instrumentation or Micrometer Tracing bridge', 'java agent', 'auto instrumentation', 'micrometer tracing', 'sdk'), kp('Export via OTLP to a Collector', 'otlp', 'collector'), kp('Backend: Jaeger, Tempo, Zipkin, vendor APM', 'jaeger', 'tempo', 'zipkin', 'apm'), kp('Sampling strategy and correlate with logs/metrics', 'sampling', 'tail sampling', 'trace id in logs', 'correlat*')],
    'A trace represents one request across services and is made of spans, one per operation such as an HTTP call or database query, linked by a trace id and propagated between services in the W3C traceparent header, including Kafka message headers. For Java I either attach the OpenTelemetry Java agent, which auto instruments Spring MVC, JDBC, HTTP clients and Kafka without code changes, or use Spring Boot 3 Micrometer Tracing with the OpenTelemetry bridge, adding custom spans for important business steps. Services export spans with OTLP to an OpenTelemetry Collector, which batches, filters, samples and forwards them to a backend such as Jaeger, Grafana Tempo or a vendor APM. I configure head or tail sampling to control cost and put the trace id in every log line.',
    'What is the difference between head-based and tail-based sampling?', src(297)),

  Q('jb-298', OB, 'SL', 'concept', 'What are the differences between metrics, logs, and traces?',
    [kp('Metrics: numeric aggregates over time, cheap, for alerting and dashboards', 'metrics', 'numeric', 'aggregat*', 'dashboard*', 'alert*'), kp('Logs: detailed discrete events with context', 'logs', 'events', 'detail*', 'context'), kp('Traces: request path across services with timing (spans)', 'traces', 'spans', 'request path', 'across services'), kp('Used together: metric alerts, trace locates, logs explain', 'together', 'correlat*', 'trace id', 'exemplar*'), kp('Cost/cardinality trade-offs', 'cost', 'cardinality', 'volume', 'sampling')],
    'Metrics are numeric measurements aggregated over time, such as request rate, error rate or heap usage. They are cheap to store, so they power dashboards and alerting, but they tell you that something is wrong rather than why, and high cardinality labels make them expensive. Logs are discrete events with rich detail and context, such as an exception with its stack trace and order id; they explain what happened but are high volume and costly to keep. Traces follow one request path across services as a tree of timed spans, showing where the latency or error occurred. They work best together: a metric alert fires, a trace locates the slow service through exemplars, and logs correlated by trace id explain the cause.',
    'What is high cardinality in metrics, and why is it a problem?', src(298)),

  Q('jb-299', SB, 'SL', 'scenario', 'How would you implement graceful shutdown in a Spring Boot application?',
    [kp('server.shutdown=graceful and timeout-per-shutdown-phase', 'server.shutdown', 'graceful', 'timeout per shutdown phase', 'spring.lifecycle'), kp('Stop accepting new requests, finish in-flight ones', 'in flight', 'stop accepting', 'finish'), kp('Kubernetes: SIGTERM, readiness probe fails, preStop delay, terminationGracePeriod', 'sigterm', 'readiness', 'prestop', 'terminationgraceperiodseconds'), kp('Stop consumers and schedulers, commit offsets, drain executors', 'kafka', 'consumer*', 'scheduler*', 'executor*', 'commit'), kp('Close resources with @PreDestroy / SmartLifecycle', 'predestroy', 'smartlifecycle', 'close')],
    'In Spring Boot I set server.shutdown=graceful and spring.lifecycle.timeout-per-shutdown-phase, for example 30 seconds. On SIGTERM the embedded server stops accepting new requests and waits for in flight requests to finish within that timeout. In Kubernetes the readiness probe should start failing so the pod is removed from the Service, and a short preStop sleep covers the delay before load balancers notice; terminationGracePeriodSeconds must be longer than the Spring timeout. Beyond HTTP, Kafka listener containers stop polling and commit offsets for processed records, schedulers stop launching new jobs, and executor services are shut down and awaited. Remaining resources are closed in PreDestroy methods or SmartLifecycle beans.',
    'What happens to an in-flight request if the grace period is shorter than the request duration?', src(299)),
];
